# Cross-check with the Python version: both must retrieve the reference values of
# inst/shared/reference/reference_values.json (generated by python/tests/make_reference.py):
# same generator, same algorithms, same starts, same permutations.

.ref <- function() {
  skip_if_not_installed("jsonlite")
  jsonlite::fromJSON(system.file("shared", "reference", "reference_values.json", package = "canofac"),
                     simplifyVector = FALSE)
}

.noise_blocks <- function() {
  g <- canofac:::.gen_new(99)
  n <- 15
  f <- canofac:::.gen_normal(g, n)
  out <- list()
  for (b in list(list("A", 4, 0.8), list("B", 5, 0.5), list("C", 6, 0))) {
    X <- matrix(canofac:::.gen_normal(g, n * b[[2]]), n, b[[2]])
    X[, 1] <- X[, 1] + b[[3]] * f
    out[[b[[1]]]] <- X
  }
  cf_preprocess(out)
}

.mat <- function(x) do.call(rbind, lapply(x, unlist))

test_that("the common generator gives the reference draws", {
  ref <- .ref()
  g <- canofac:::.gen_new(1)
  expect_equal(canofac:::.gen_uniform(g, 5), unlist(ref$rng$uniform_seed1), tolerance = 1e-15)
  expect_equal(unname(cf_permutations(3, 7, seed = 11)), .mat(ref$rng$permutations_seed11_B3_n7))
  expect_equal(canofac:::.gen_normal(canofac:::.gen_new(12345), 4), unlist(ref$rng$normal_seed12345),
               tolerance = 1e-12)
})

test_that("the fits are those of the Python version", {
  ref <- .ref()
  bl <- .test_blocks()
  for (e in ref$fits) {
    f <- canofac(bl, R = 2, q = e$q, axes = e$axes, extraction = e$extraction)
    expect_equal(f$criterion, e$criterion, tolerance = 1e-7)
    slow <- (e$q == 1 && e$axes == "free") || (e$q == 2 && e$axes == "orthonormal" && e$extraction == "simultaneous")
    expect_equal(unname(f$d), .mat(e$d), tolerance = if (slow) 2e-3 else 1e-6)
  }
})

test_that("the permutation tests give the same p-values as the Python version", {
  ref <- .ref()
  bl <- .noise_blocks()
  expect_equal(unname(bl$A[1, ]), unlist(ref$noise_blocks_first_row$A), tolerance = 1e-10)
  for (e in ref$tests) {
    args <- c(list(blocks = bl, R = 2, B = e$B, seed = e$seed), lapply(e$kw, function(v)
      if (is.list(v)) unlist(v) else v))
    r <- do.call(cf_test, args)
    expect_equal(unname(r$p), .mat(e$p), tolerance = 1e-10, label = e$name)
    expect_equal(unname(r$p_subspace), unlist(e$p_subspace), tolerance = 1e-10, label = e$name)
    expect_equal(unname(r$link), unlist(e$link), label = e$name)
    expect_equal(r$link_subspace, e$link_subspace, label = e$name)
  }
})

test_that("the exact permutation moments are those of the Python version", {
  ref <- .ref()
  bl <- .test_blocks()
  u <- svd(cbind(bl$B, bl$C))$u[, 1:2]
  m <- perm_moments(tcrossprod(bl$A), tcrossprod(u))
  expect_equal(unname(m), c(ref$moments$mean, ref$moments$var), tolerance = 1e-10)
})

test_that("the simulated data are those of the Python version", {
  ref <- .ref()
  sim <- cf_simulate("SD", n = 12, p = 5, K = 3, theta = 1.8, seed = 7)
  for (k in names(ref$simulate_SD))
    expect_equal(unname(sim[[k]][1:2, ]), .mat(ref$simulate_SD[[k]]), tolerance = 1e-10)
})
